import{z as n,x as s,o as e,c as i,q as t,j as o,D as a,d as l,s as A,S as B}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"TensorRT-LLM 走读","description":"","frontmatter":{"title":"TensorRT-LLM 走读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-tensorrt-llm-walkthrough.md","filePath":"llm/fw-tensorrt-llm-walkthrough.md","lastUpdated":1791413859000}'),h={name:"llm/fw-tensorrt-llm-walkthrough.md"};function d(D,E,p,C,m,T){const r=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=t('<h1 id="tensorrt-llm-走读" tabindex="-1">TensorRT-LLM 走读 <a class="header-anchor" href="#tensorrt-llm-走读" aria-label="Permalink to &quot;TensorRT-LLM 走读&quot;">​</a></h1><div class="epigraph"><p>有的框架把聪明放在运行期，这一个把聪明浇筑进构建期：内核选择、量化、形状，都在你按下构建按钮时定局。</p><footer>—— 据 NVIDIA TensorRT-LLM 官方仓库与文档整理</footer></div><p><a href="/llm/fw-sglang-walkthrough">上一课</a>在 SGLang 仓库里看到的是纯 Python 运行时：决策、组批、执行都在解释器里跑。TensorRT-LLM 把重心翻到构建期——能力面已写过：编引擎换峰值、在环推理即服务是它的取舍，见 <a href="/llm/tensorrt-llm">TensorRT-LLM</a>。本课进仓库讲它的两段式结构与关键数据物，以仓库当时状态为准。它是六个走读对象里版本迭代最激进的，本课只讲不随版本翻面的骨架。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>按 Python 运行时的读法进来会迷路：仓库里几乎找不到「调度器类」，也找不到逐 token 的采样循环。原因在于它把一次前向的计算图在<strong>构建期</strong>编译成序列化的引擎计划，运行期只剩一个薄薄的执行接口，真正的组批与 KV 管理沉在 C++ 运行库里。于是走读的问题变成两问：构建期把哪些决策浇死了，运行期还留着哪些自由度。</p><h3 id="构建期-图、权重、引擎三件分离" tabindex="-1">构建期：图、权重、引擎三件分离 <a class="header-anchor" href="#构建期-图、权重、引擎三件分离" aria-label="Permalink to &quot;构建期：图、权重、引擎三件分离&quot;">​</a></h3><p>模型定义目录里，每个支持的结构有一份用框架原语写成的<strong>无权重图</strong>：层怎么摆、并行怎么切、量化怎么插，都是图里的节点。权重转换脚本把开源检查点映射到这张图的名字空间。构建器吃进图与权重配置，产出序列化的引擎计划文件——这一步做完，内核选择、融合、精度路径就不再改变。运行期的执行器持有引擎实例，对外暴露请求应答式接口：提交请求、流式收回增量结果。KV 缓存管理器在运行期按块记账，但块的总预算在构建期由配置算定。</p>',7)),(e(),o(B,null,{default:a(()=>[A(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E6%97%A0%E6%9D%83%E9%87%8D%E6%A8%A1%E5%9E%8B%E5%9B%BE%22%5D%20--%3E%20BLD%5B%22%E6%9E%84%E5%BB%BA%E5%99%A8%22%5D%0A%20%20CKPT%5B%22%E6%9D%83%E9%87%8D%E8%BD%AC%E6%8D%A2%E8%84%9A%E6%9C%AC%22%5D%20--%3E%20BLD%0A%20%20CFG%5B%22%E5%B9%B6%E8%A1%8C%20%2F%20%E9%87%8F%E5%8C%96%20%2F%20%E5%BD%A2%E7%8A%B6%E9%85%8D%E7%BD%AE%22%5D%20--%3E%20BLD%0A%20%20BLD%20--%3E%7C%E5%BA%8F%E5%88%97%E5%8C%96%7C%20ENG%5B%22%E5%BC%95%E6%93%8E%E8%AE%A1%E5%88%92%E6%96%87%E4%BB%B6%22%5D%0A%20%20ENG%20--%3E%20EXE%5B%22%E6%89%A7%E8%A1%8C%E5%99%A8%EF%BC%88Python%20%E6%8E%A5%E5%8F%A3%EF%BC%89%22%5D%0A%20%20EXE%20--%3E%20CPP%5B%22C%2B%2B%20%E8%BF%90%E8%A1%8C%E5%BA%93%EF%BC%9A%E7%BB%84%E6%89%B9%20%2B%20KV%20%E7%AE%A1%E7%90%86%20%2B%20%E6%8A%95%E6%9C%BA%E6%A8%A1%E5%9D%97%22%5D%0A%20%20CPP%20--%3E%7C%E6%B5%81%E5%BC%8F%E5%93%8D%E5%BA%94%7C%20EXE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<p><span class="marginnote">引擎计划绑定形状范围：构建时声明的最大批、最长序列不是建议而是上限，超界请求在运行期被拒。换部署档位要重编引擎——这是「编引擎换峰值」字面上的代价。</span></p><p><span class="marginnote">「序列化引擎计划」翻译一下：把计算图、选好的内核、融合与量化路径打包成一个二进制文件，加载时不再做任何搜索或编译决策。就像菜谱连火候提前定死、装进饭盒，开餐之后只管照着热——快，但中途换不了菜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>走读同样沿一步迭代走，但要在 C++ 侧找锚点。一步的内容是：执行器收进一批请求，运行库里的批管理器决定本步跑谁——上下文阶段的请求与解码阶段的请求如何混批，是它内部的策略点；KV 管理器按块表给本步分配写槽；引擎计划里的核依次执行前向；采样在运行库侧完成，token 经执行器流回。三个关键数据物对应三段：引擎配置记构建期决策，块表记 KV 账，请求应答对象记会话生命周期。投机的草稿验证、逐批日志、每层计时都在运行库挂了钩子，读性能问题的入口在 C++ 侧而不在 Python 侧。</p><p><span class="marginnote">给个数代入 KV 池预算：设每块 16 token、构建期配 4096 块，池子总量就是 \\(4096 \\times 16\\) 个 token 槽，再乘层数、KV 头维度与精度字节数折成显存。运行期只能在这笔定死的账内分配，满了就只能抢占或拒绝——预算不是运行期参数。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两段式买来的是热路径的确定性。内核在构建期选定，就没有运行期分派开销；批管理与 KV 记账沉进编译后的代码，Python 解释器只留在接口层；FP8、INT4 这类平台量化在构建期作为图变换写进计划，而不是运行期的转换钩子。代价同样清楚：形状、并行、精度任一变化都要重编，工程节奏从「改配置」变成「走构建流水线」。这也是它与前两课的对照点：vLLM 与 SGLang 把调度器放在仓库最显眼处，因为那里每步都在重新决策；这里的调度自由度被压缩进批管理器内部，仓库的复杂度则堆在构建期——图原语、权重映射与引擎配置的数量，才是它的真实表面积。</p>',7)),(e(),o(B,null,{default:a(()=>[A(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E4%B8%80%E6%AD%A5%E8%BF%AD%E4%BB%A3%E5%BC%80%E5%A7%8B%22%5D%20--%3E%20BM%5B%22%E6%89%B9%E7%AE%A1%E7%90%86%E5%99%A8%EF%BC%9A%E6%9C%AC%E6%AD%A5%E8%B7%91%E8%B0%81%22%5D%0A%20%20BM%20--%3E%20MIX%7B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E8%AF%B7%E6%B1%82%E4%B8%8E%E8%A7%A3%E7%A0%81%E8%AF%B7%E6%B1%82%E6%B7%B7%E6%89%B9%EF%BC%9F%22%7D%0A%20%20MIX%20--%3E%7C%22%E5%86%B3%E5%AE%9A%22%7C%20KBM%5B%22KV%20%E7%AE%A1%E7%90%86%E5%99%A8%E6%8C%89%E5%9D%97%E8%A1%A8%E5%88%86%E9%85%8D%E5%86%99%E6%A7%BD%22%5D%0A%20%20KBM%20--%3E%20FWD%5B%22%E5%BC%95%E6%93%8E%E8%AE%A1%E5%88%92%E5%86%85%E7%9A%84%E6%A0%B8%E4%BE%9D%E6%AC%A1%E5%89%8D%E5%90%91%22%5D%0A%20%20FWD%20--%3E%20SAMP%5B%22%E8%BF%90%E8%A1%8C%E5%BA%93%E4%BE%A7%E9%87%87%E6%A0%B7%22%5D%0A%20%20SAMP%20--%3E%20OUT%5B%22token%20%E7%BB%8F%E6%89%A7%E8%A1%8C%E5%99%A8%E6%B5%81%E5%9B%9E%E8%B0%83%E7%94%A8%E6%96%B9%22%5D%0A%20%20OUT%20--%3E%7C%22%E4%B8%8B%E4%B8%80%E6%AD%A5%22%7C%20BM%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">初学者容易以为换量化精度就是改个开关，实际上 FP8、INT4 在这套架构里是构建期的图变换，写进了引擎计划——不重编引擎就不生效。这一步做错（想在线切精度）会直接撞墙，正确路径是走构建流水线另出一版引擎。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的骨架描述是版本敏感度最高的一篇：执行器接口的形态、是否走纯运行时路径、PyTorch 后端的地位，仓库都翻过面，以仓库当时状态为准；具体类名不引用。它只覆盖 NVIDIA 平台，跨厂商不是它的主场；也不给这个产品仓库安会议论文，出处口径是官方仓库与文档。逐能力清单见概念课，本课不重列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TensorRT-LLM 是两段式：构建期把无权重图、权重、量化与形状浇成序列化引擎计划，运行期只留薄接口。</li><li>调度不在 Python 里：组批、KV 记账、采样沉在 C++ 运行库，走读锚点是批管理器与块表。</li><li>引擎计划绑定形状上限，换部署档位要重编，这是峰值与灵活性之间的兑换率。</li><li>与 vLLM、SGLang 对照：仓库表面积在构建期，运行期自由度被刻意压小。</li><li>版本敏感度全组最高，骨架以仓库当时状态为准，出处是官方仓库与文档。</li></ul>',5))])}const u=n(h,[["render",d]]);export{P as __pageData,u as default};
